127	    /**
128	     * Writes this descriptor to a DataOutputStream, including the magic number prefix.
129	     */
130	    public void writeTo(DataOutputStream out) throws IOException {
131	        out.writeInt(MAGIC);
132	        writeFieldsTo(out);
133	        out.flush();
134	    }
