136	    /**
137	     * Writes the fields of this descriptor without the magic number prefix.
138	     * Subclasses can call this to embed base fields in their own wire format.
139	     */
140	    protected void writeFieldsTo(DataOutputStream out) throws IOException {
141	        out.writeUTF(command);
142	        writeStringList(out, jvmOptions);
143	        writeStringList(out, jvmArgs);
144	        writeStringMap(out, environment);
145	        out.writeUTF(workingDir);
146	        out.writeUTF(tempDir);
147	        out.writeBoolean(daemonize);
148	        out.writeInt(serverArgsBytes.length);
149	        out.write(serverArgsBytes);
150	    }
