169	    /**
170	     * Reads descriptor fields without the magic number prefix.
171	     * Subclasses can call this to read base fields from their own wire format.
172	     */
173	    protected static LaunchDescriptor readFieldsFrom(DataInputStream in) throws IOException {
174	        String command = in.readUTF();
175	        List<String> jvmOptions = readStringList(in);
176	        List<String> jvmArgs = readStringList(in);
177	        Map<String, String> environment = readStringMap(in);
178	        String workingDir = in.readUTF();
179	        String tempDir = in.readUTF();
180	        boolean daemonize = in.readBoolean();
181	        int serverArgsBytesLen = in.readInt();
182	        byte[] serverArgsBytes = in.readNBytes(serverArgsBytesLen);
183	        if (serverArgsBytes.length != serverArgsBytesLen) {
184	            throw new IOException("Truncated server args: expected " + serverArgsBytesLen + " bytes, got " + serverArgsBytes.length);
185	        }
186	
187	        return new LaunchDescriptor(command, jvmOptions, jvmArgs, environment, workingDir, tempDir, daemonize, serverArgsBytes);
188	    }
