190	    /**
191	     * Checks the magic number from the stream and throws if it doesn't match.
192	     */
193	    protected static void checkMagic(DataInputStream in, int expectedMagic) throws IOException {
194	        int magic = in.readInt();
195	        if (magic != expectedMagic) {
196	            throw new IOException("Invalid launch descriptor: bad magic number");
197	        }
198	    }
