200	    /**
201	     * Returns a human-readable representation of this descriptor in a section-based text format.
202	     * Useful for debugging with the launcher's --dump flag.
203	     */
204	    public String toHumanReadable() {
205	        StringBuilder sb = new StringBuilder();
206	
207	        appendSection(sb, "command", command);
208	        appendSection(sb, "working_dir", workingDir);
209	        appendSection(sb, "temp_dir", tempDir);
210	        appendSection(sb, "daemonize", String.valueOf(daemonize));
211	        appendSection(sb, "server_args_bytes", "<" + serverArgsBytes.length + " bytes>");
212	
213	        sb.append("[jvm_options]\n");
214	        for (String opt : jvmOptions) {
215	            sb.append(opt).append('\n');
216	        }
217	        sb.append('\n');
218	
219	        sb.append("[jvm_args]\n");
220	        for (String arg : jvmArgs) {
221	            sb.append(arg).append('\n');
222	        }
223	        sb.append('\n');
224	
225	        sb.append("[environment]\n");
226	        for (Map.Entry<String, String> entry : environment.entrySet()) {
227	            sb.append(entry.getKey()).append('=').append(entry.getValue()).append('\n');
228	        }
229	
230	        return sb.toString();
231	    }
