 30	    /**
 31	     * Round-trip via DataOutputStream/DataInputStream: write descriptor to bytes, read back, assert all fields match.
 32	     */
 33	    public void testRoundTripViaStreams() throws IOException {
 34	        LaunchDescriptor original = descriptorWithSampleData();
 35	        ByteArrayOutputStream baos = new ByteArrayOutputStream();
 36	        try (DataOutputStream out = new DataOutputStream(baos)) {
 37	            original.writeTo(out);
 38	        }
 39	        LaunchDescriptor readBack;
 40	        try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(baos.toByteArray()))) {
 41	            readBack = LaunchDescriptor.readFrom(in);
 42	        }
 43	        assertDescriptorEquals(original, readBack);
 44	    }
